<template>
  <section class="mt-panel" v-loading="loading">
    <header><el-radio-group v-model="source" @change="reset" aria-label="评价来源"><el-radio-button value="美团评价">美团评价</el-radio-button><el-radio-button value="点评评价">点评评价</el-radio-button><el-radio-button value="all">全部来源</el-radio-button></el-radio-group><p>采集记录 · {{ stamp(result.updatedAt) }} 更新</p></header>
    <el-alert v-if="error" :title="error" type="error" :closable="false"/>
    <template v-else>
      <div class="mt-summary"><article v-for="metric in metrics" :key="metric.key"><small>{{ metric.label }}</small><strong>{{ result.summary?.[metric.key] ?? 0 }}<em>条</em></strong></article></div>
      <p class="mt-note">{{ mode==='full' ? '全部已采集评价' : '近七天：'+(result.dateRange || '') }} · 评分为平台采集快照，评价统计按下方时间范围。</p>
      <el-table v-if="multipleStores && result.stores?.length" :data="result.stores" stripe>
        <el-table-column prop="storeName" label="门店" min-width="210" fixed/>
        <el-table-column label="美团评分" width="110"><template #default="{row}">{{ score(row,'美团评价') }}</template></el-table-column>
        <el-table-column label="点评评分" width="110"><template #default="{row}">{{ score(row,'点评评价') }}</template></el-table-column>
        <el-table-column v-for="metric in metrics" :key="metric.key" :prop="metric.key" :label="metric.label" min-width="110" align="right"/>
        <el-table-column label="已回复比例" width="120" align="right"><template #default="{row}">{{ percent(row.replyRate) }}</template></el-table-column>
      </el-table>
      <div v-else-if="result.stores?.length" class="mt-store"><div class="mt-store-title"><strong>{{ result.stores[0].storeName }}</strong><span>{{ result.stores[0].city }}</span></div><div class="mt-score-cards"><article v-for="name in activeSources" :key="name" class="mt-score-card"><div class="mt-score-heading"><el-tag size="small" effect="plain">{{ name }}</el-tag><span>平台累计 {{ result.stores[0].sources?.[name]?.total ?? '—' }} 条评价</span></div><div class="mt-score-number"><b>{{ score(result.stores[0],name) }}</b><el-rate :model-value="Number(score(result.stores[0],name)) || 0" disabled allow-half/></div><p class="mt-score-change">较昨日 <strong>{{ result.stores[0].sources?.[name]?.metrics?.scoreChange || '—' }}</strong></p><div class="mt-dimensions"><div v-for="(value,label) in result.stores[0].sources?.[name]?.metrics?.dimensions || {}" :key="label"><small>{{ label }}</small><strong>{{ value.toFixed(1) }}</strong><div class="mt-dimension-track"><i :style="{width:value/5*100+'%'}"></i></div></div></div></article></div></div>
      <div v-if="result.stores?.length" class="mt-chart-wrap"><div class="mt-chart-title"><h4>评价分析</h4><div class="mt-chart-controls"><el-radio-group v-model="chartMode" @change="loadChart" size="small" aria-label="评价分析时间范围"><el-radio-button value="full">全部评价</el-radio-button><el-radio-button value="recent7">近七天评价</el-radio-button></el-radio-group><span class="mt-chart-date">{{ chartMode==='recent7' ? chartDateRange : '全部已采集评价' }}</span></div></div><div v-loading="chartLoading" class="mt-chart-stage" :aria-busy="chartLoading"><div ref="chartEl" class="mt-chart" :class="{'is-switching':chartLoading}"></div></div><p v-if="chartError" class="mt-chart-error" role="alert">{{ chartError }}</p></div>
      <el-empty v-else description="所选门店暂无已关联的美团评价" :image-size="70"/>
      <div class="mt-tools"><h4>顾客评价</h4><el-radio-group v-model="mode" @change="reset"><el-radio-button value="full">全部评价</el-radio-button><el-radio-button value="recent7">近七天评价</el-radio-button></el-radio-group><el-checkbox v-model="textOnly" @change="reset">隐藏无文字评价</el-checkbox><span>共 {{ result.total || 0 }} 条</span></div>
      <div class="mt-star-filter"><span>评价星级</span><el-checkbox :model-value="selectedStars.length===stars.length" :indeterminate="selectedStars.length>0 && selectedStars.length<stars.length" @change="toggleAllStars">全选</el-checkbox><el-checkbox-group v-model="selectedStars" aria-label="评价星级勾选"><el-checkbox v-for="star in stars" :key="star" :value="star">{{ star }} 星</el-checkbox></el-checkbox-group><el-button type="primary" size="small" :loading="loading" @click="queryStars">查询</el-button><small v-if="starsDirty">星级筛选已修改，点击查询生效</small></div>
      <article v-for="review in result.reviews" :key="review.platformStoreId+review.source+review.reviewId" class="mt-review">
        <div class="mt-review-head"><strong>{{ review.customerName || '顾客' }}</strong><el-tag v-if="review.returningCustomer" size="small" type="warning" effect="plain">回头客</el-tag><el-tag size="small" :type="review.rating>=4?'success':'warning'">{{ review.rating>0?review.rating+' 星':'未评分' }}</el-tag><time>评价时间 {{ review.publishedDisplay || '未提供' }}</time></div>
        <div class="mt-review-meta"><span>{{ review.storeName }}</span><span>{{ review.source }}</span><span v-if="review.reviewType">{{ review.reviewType }}</span><span v-if="!review.returningCustomer">回头客：平台未标记</span><span v-for="(value,name) in review.dimensions" :key="name">{{ name }} {{ value.toFixed(1) }}</span></div>
        <div v-for="(coupon,index) in review.coupons" :key="index" class="mt-coupon"><span class="mt-coupon-label">消费券</span><strong>{{ coupon.name }}</strong><span v-if="coupon.price">¥{{ coupon.price }}</span><span v-if="coupon.verifiedDisplay">{{ coupon.verifiedDisplay }}核销</span></div>
        <p>{{ review.text || '顾客未填写文字评价' }}</p>
        <div v-if="review.media?.length" class="mt-review-media"><el-image v-for="(url,index) in review.media" :key="url" :src="url" :preview-src-list="review.media" :initial-index="index" preview-teleported fit="cover" loading="lazy"><template #error><span>图片暂不可用</span></template></el-image></div>
        <div v-if="conversationGroups(review).length" class="mt-conversation">
          <div v-for="(group,index) in conversationGroups(review)" :key="index" class="mt-thread-item" :class="group.role==='merchant'?'mt-reply':'mt-customer-reply'">
            <div class="mt-thread-avatar" aria-hidden="true">{{ group.role==='merchant'?'商':'客' }}</div>
            <div class="mt-thread-content"><div class="mt-thread-head"><strong>{{ group.role==='merchant'?'商家':group.author || '顾客' }}</strong><span>{{ group.role==='merchant'?'商家回复':'顾客追评' }}</span><time>{{ group.publishedDisplay }}</time></div><p>{{ group.text }}</p>
              <div v-for="(reply,replyIndex) in group.children" :key="replyIndex" class="mt-thread-followup"><div class="mt-thread-head"><strong>{{ reply.author || '顾客' }}</strong><span>回复商家</span><time>{{ reply.publishedDisplay }}</time></div><p>{{ reply.text }}</p></div>
            </div>
          </div>
        </div>
      </article>
      <el-empty v-if="!loading && !result.reviews?.length && result.stores?.length" description="当前筛选暂无评价" :image-size="60"/>
      <el-pagination v-model:current-page="page" v-model:page-size="pageSize" :total="result.total || 0" :page-sizes="[10,20,50,100]" layout="total, sizes, prev, pager, next" @size-change="reset" @current-change="load"/>
    </template>
  </section>
</template>
<script setup>
import {computed,ref,watch,nextTick,onBeforeUnmount} from 'vue';
import * as echarts from 'echarts';
import {getMeituanReviews} from '@/api';
import {validReviewScope} from '@/utils/analysis-query-gate.mjs';
const props=defineProps({scope:{type:Object,default:()=>({})}});
const multipleStores=computed(()=>new Set(String(props.scope.store_ids||props.scope.store_id||'').split(',').filter(Boolean)).size>1);
const metrics=[{key:'total',label:'采集评价'},{key:'positive',label:'好评'},{key:'negative',label:'中差评'},{key:'textCount',label:'有文字评价'},{key:'replied',label:'已回复评价'}];
const stars=Array.from({length:10},(_,i)=>(i+1)/2);
const selectedStars=ref([...stars]),appliedStars=ref([...stars]),pageSize=ref(20);
const starsDirty=computed(()=>JSON.stringify(selectedStars.value)!==JSON.stringify(appliedStars.value));
function queryStars(){appliedStars.value=[...selectedStars.value];reset();}
function toggleAllStars(checked){selectedStars.value=checked?[...stars]:[];}
const activeSources=computed(()=>source.value==='all'?['美团评价','点评评价']:[source.value]);
const source=ref('美团评价'),mode=ref('recent7'),textOnly=ref(true),page=ref(1),loading=ref(false),error=ref(''),result=ref({stores:[],reviews:[]}),chartEl=ref();
const stamp=v=>v?new Date(v).toLocaleString('zh-CN',{hour12:false}):'尚未采集';
const percent=v=>v==null?'—':v+'%';
const score=(row,name)=>row.sources?.[name]?.metrics?.score || '—';
function conversationGroups(review){
 const rows=review.conversation || (review.merchantReplies||[]).map(r=>({...r,role:'merchant'})),groups=[];
 for(const row of rows){const last=groups[groups.length-1];if(row.role==='customer'&&/^回复商家\s*[:：]/.test(row.text||'')&&last?.role==='merchant')last.children.push(row);else groups.push({...row,children:[]});}
 return groups;
}
const chartMode=ref('recent7'),chartSummary=ref({}),chartLoading=ref(false),chartDateRange=ref(''),chartError=ref('');
let sequence=0,chartSequence=0,chart;
async function loadChart(){
 if(!validReviewScope(props.scope))return;
 const id=++chartSequence;chartLoading.value=true;chartError.value='';
 try{const data=await getMeituanReviews({...props.scope,source:source.value,mode:chartMode.value,page_size:10,page:1});
  if(id!==chartSequence)return;chartSummary.value=data.summary||{};chartDateRange.value=data.dateRange||'';await nextTick();render();
 }catch(e){if(id===chartSequence){chartSummary.value={};chartError.value=e.message||'评价分析加载失败';render();}}
 finally{if(id===chartSequence)chartLoading.value=false;}
}
function render(){
 if(!chartEl.value){chart?.dispose();chart=null;return;}
 if(chart&&chart.getDom()!==chartEl.value){chart.dispose();chart=null;}
 chart=chart||echarts.init(chartEl.value);
 const summary=chartSummary.value||{},width=chartEl.value.clientWidth,compact=width<700;
 const pieX=compact?width/2:width*.21,barLeft=compact?50:width*.47,barCenter=(barLeft+width-30)/2;
 chart.setOption({animationDuration:450,animationDurationUpdate:450,animationEasingUpdate:'cubicOut',color:['#64b98a','#ee8a91','#c5cfdd'],tooltip:{trigger:'item'},title:[{text:'评价占比',left:pieX,textAlign:'center',top:10,textStyle:{fontSize:13,color:'#526780'}},{text:'星级分布',left:barCenter,textAlign:'center',top:compact?265:10,textStyle:{fontSize:13,color:'#526780'}}],legend:{left:pieX-83,padding:0,itemGap:14,top:compact?225:255,data:['好评','中差评','未评分'],icon:'circle',itemWidth:9,textStyle:{fontSize:12,fontFamily:'sans-serif',color:'#75859a'}},grid:{left:compact?50:'47%',right:30,top:compact?300:60,bottom:35},xAxis:{type:'category',data:(summary.stars||[]).map(s=>s.rating+'星'),axisTick:{show:false},axisLine:{lineStyle:{color:'#e6edf5'}},axisLabel:{color:'#8695a8',interval:0,rotate:compact?45:0}},yAxis:{type:'value',minInterval:1,axisLabel:{color:'#8695a8'},splitLine:{lineStyle:{color:'#f0f3f8'}}},series:[{id:'review-share',type:'pie',radius:[compact?55:65,compact?85:95],center:compact?['50%',125]:['21%',145],label:{show:false},emphasis:{label:{show:true,formatter:'{b}\n{c}条 · {d}%',fontSize:13}},itemStyle:{borderColor:'#fff',borderWidth:4,borderRadius:5},data:[{name:'好评',value:summary.positive||0},{name:'中差评',value:summary.negative||0},{name:'未评分',value:summary.unrated||0}]},{id:'review-stars',name:'评价数',type:'bar',barMaxWidth:25,itemStyle:{borderRadius:[5,5,0,0]},label:{show:true,position:'top',color:'#718198',formatter:p=>p.value||''},data:(summary.stars||[]).map(s=>({value:s.count,itemStyle:{color:s.rating>=4?'#64b98a':'#ee8a91'}}))}]});
}
async function load(){if(!validReviewScope(props.scope))return;const id=++sequence;loading.value=true;error.value='';try{const data=await getMeituanReviews({...props.scope,source:source.value,mode:mode.value,ratings:appliedStars.value.join(','),page_size:pageSize.value,text_only:textOnly.value?'1':'0',page:page.value});if(id!==sequence)return;result.value=data;await nextTick();render();}catch(e){if(id===sequence){error.value=e.message||'评价加载失败';chart?.dispose();chart=null;}}finally{if(id===sequence)loading.value=false;}}
function reset(){page.value=1;load();}
watch(()=>JSON.stringify(props.scope),reset,{immediate:true});
watch(()=>JSON.stringify([props.scope,source.value]),loadChart,{immediate:true});
const observer=new ResizeObserver(()=>{chart?.resize();render();});watch(chartEl,el=>{observer.disconnect();if(el)observer.observe(el);});
onBeforeUnmount(()=>{sequence++;chartSequence++;observer.disconnect();chart?.dispose();});
</script>
